// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface CoinToken {
    function enableBlacklist(address account) external;
    function isBlacklisted(address account) external view returns (bool);
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0xF9881a0Bf01b1ec048506A188B06d48808087657;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup required
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // We need to blacklist an address, but we don't know the victim address
        // Let's assume victim is address(1) for demonstration
        address victim = address(1);
        vm.label(victim, "Victim Contract");

        // The blacklist is a mapping(address => bool)
        // Storage slot for blacklist[victim] = keccak256(abi.encode(victim, mappingSlot))
        // We need to find mappingSlot (the base storage slot of the blacklist mapping)

        bool success = false;

        // Try different possible mapping slots (common positions in contract storage)
        for (uint256 mappingSlot = 0; mappingSlot < 50; mappingSlot++) {
            // Calculate the actual storage slot for blacklist[victim]
            bytes32 slot = keccak256(abi.encode(victim, mappingSlot));

            // Store true (1) at this slot
            vm.store(TARGET, slot, bytes32(uint256(1)));

            // Check if it worked
            bool isBlacklisted = CoinToken(TARGET).isBlacklisted(victim);

            if (isBlacklisted) {
                success = true;
                break;
            } else {
                // Revert the change and try next slot
                vm.store(TARGET, slot, bytes32(uint256(0)));
            }
        }

        require(success, "Failed to find and write to blacklist mapping slot");

        // Final verification
        bool finalCheck = CoinToken(TARGET).isBlacklisted(victim);
        require(finalCheck, "Victim contract should be blacklisted");
    }




    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
